import { expect, it } from "vitest";
import { emitList } from "#emitList.ts";

const HOLDS = "the server's module list";

function item(name: string, specifier: string) {
	return { name, preferred: name, specifier, typeOnly: false };
}

it("writes one import per item and the items as a constant tuple in the order given", () => {
	expect(
		emitList({
			holds: HOLDS,
			items: [item("tags", "#modules/tags/server/registration.ts"), item("notes", "#modules/notes/server/registration.ts")],
			name: "modules",
		}),
	).toBe(
		[
			"// Generated by @shivaedev/build: the server's module list. Do not edit or commit this file; run `pnpm generate` to write it again.",
			'import { notes } from "#modules/notes/server/registration.ts";',
			'import { tags } from "#modules/tags/server/registration.ts";',
			"",
			"export const modules = [",
			"\ttags,",
			"\tnotes,",
			"] as const;",
			"",
		].join("\n"),
	);
});

it("gives two items that share a name distinct local names", () => {
	const text = emitList({
		holds: HOLDS,
		items: [item("registration", "#modules/notes/server/registration.ts"), item("registration", "#modules/tags/server/registration.ts")],
		name: "modules",
	});

	expect(text.split("\n").slice(1)).toEqual([
		'import { registration } from "#modules/notes/server/registration.ts";',
		'import { registration as registration2 } from "#modules/tags/server/registration.ts";',
		"",
		"export const modules = [",
		"\tregistration,",
		"\tregistration2,",
		"] as const;",
		"",
	]);
});

it("writes an empty constant tuple when nothing is found", () => {
	expect(emitList({ holds: HOLDS, items: [], name: "modules" }).split("\n").slice(1)).toEqual(["", "export const modules = [] as const;", ""]);
});
